head.script:
scwin.test_submit = function() {
    //alert(1234);
};
scwin.test_submit2 = function() {
    alert(4567);
};
scwin.trigger1_onclick = function(e) {
    var tmpOpt = {
        id: "submission123",
        ref: "",
        target: "data:json,dataList1",
        action: "test.json",
        mediatype: "application/json",
        processMsg: "처리중입니다.",
        abortTrigger: "true",
        submitHandler: "scwin.test_submit",
        submitDoneHandler: "scwin.test_submit2"
    };
    $w.createSubmission(tmpOpt);
    scwin.$w.executeSubmission("submission123");
}
scwin.trigger2_onclick = function(e) {
    WebSquare.ModelUtil.abort("submission1");
};
scwin.submission1_submitdone = function(e) {
    alert("완료");
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "$w.getSubmission('submission123').submitDoneHandler == 'scwin.test_submit2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "$w.getSubmission('submission123').submitHandler == 'scwin.test_submit'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
